import {ToolRegistry} from './registry.js';

describe('ToolRegistry runtime compatibility', () => {
  // @spec specs/hal-engine-tool-input-validation/spec.md#11
  it('loads the registry and rejects a numeric location', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather by location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
      },
      async input => JSON.stringify(input)
    );

    await expect(registry.execute('weather', {location: 123})).resolves.toEqual({
      result: expect.stringMatching(/location.*string/),
    });
  });
});
EOF
